  let image = &quot;Illustrations/PNJ/Tengu.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Tengu (race).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Tengu.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Tengu-(Race).html&quot; title=&quot;Les tengus&quot;&gt;tengus&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Chemise du mangeur de malchance&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Races de la mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea Races/Races de la mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Abjuration.html&quot; title=&quot;Abjuration&quot;&gt;Abjuration&lt;/a&gt; mod&#233;r&#233;e ; &lt;b&gt;NLS&lt;/b&gt; 8 ; &lt;b&gt;Emplacement&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Port&#233;s-Sur-Le-Torse.html&quot; title=&quot;Objets merveilleux port&#233;s sur le torse&quot;&gt;torse&lt;/a&gt; ; &lt;b&gt;Prix&lt;/b&gt; 22.600 po ; &lt;b&gt;Poids&lt;/b&gt; 0.5 kg
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Cette chemise est cousue d&#39;une douzaine de symboles visant &#224; attirer la mauvaise fortune, notamment des yeux inject&#233;s de sang et des cr&#226;nes de &lt;a class=&quot;pagelink&quot; href=&quot;Tengu-(Race).html&quot; title=&quot;Les tengus&quot;&gt;tengu&lt;/a&gt;. Lorsqu&#39;un alli&#233; dans un rayon de 18 m&#232;tres est soumis &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;mal&#233;diction&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html#MALEFICE&quot; title=&quot;La sorci&#232;re&quot;&gt;mal&#233;fice&lt;/a&gt;, un mauvais sort ou un autre effet qui le forcerait &#224; lancer plusieurs fois le m&#234;me jet pour conserver le pire r&#233;sultat, un porteur tengu peut tenter de manger l&#39;effet par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;. Le porteur de la chemise effectue un test de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; contre un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de 11 + le niveau de lanceur de sorts de la source de l&#39;effet (ou son nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; si cette source n&#39;a pas de niveau de lanceur de sorts). Sur une r&#233;ussite, le porteur est soumis &#224; l&#39;effet &#224; la place de sa cible originale et obtient un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort#Pvtemporaires.html&quot; title=&quot;points de vie temporaires&quot;&gt;points de vie temporaires&lt;/a&gt; &#233;gal au niveau de lanceur de sorts de l&#39;effet ou au nombre de DV de la cible, selon le moins &#233;lev&#233;. Ces points de vie temporaires persistent pendant 1 minute. Une &lt;i&gt;chemise du mangeur de malchance&lt;/i&gt; ne peut rediriger qu&#39;un effet provenant d&#39;une cr&#233;ature donn&#233;e par jour, mais il n&#39;y a pas d&#39;autre limite &#224; son utilisation.
&lt;div class=&quot;box&quot;&gt;Cr&#233;ation&lt;/div&gt;
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Dobjets-Merveilleux.html&quot; title=&quot;Cr&#233;ation d&amp;#39;objets merveilleux&quot;&gt;Cr&#233;ation d&#39;objets merveilleux&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;livrance-Des-Mal&#233;dictions.html&quot; title=&quot;D&#233;livrance des mal&#233;dictions&quot;&gt;d&#233;livrance des mal&#233;dictions&lt;/a&gt;&lt;/i&gt;, le cr&#233;ateur doit &#234;tre un &lt;a class=&quot;pagelink&quot; href=&quot;Tengu-(Race).html&quot; title=&quot;Les tengus&quot;&gt;tengu&lt;/a&gt; ; &lt;b&gt;Co&#251;t&lt;/b&gt; 11.300 po
&lt;/div&gt;
